from math import gcd
from collections import deque

INF = float("inf")

def cf_steps(p: int, q: int) -> int:
    # ops needed to turn coefficient rows (1,0),(0,1) into one row (p,q): sum of Euclid quotients
    s = 0
    while q:
        s += p // q
        p, q = q, p % q
    return s

def positive(a: int, b: int, n: int) -> float:
    # a, b > 0, n not in (a, b): every reachable value is p*a + q*b with gcd(p, q) = 1
    big, small = max(a, b), min(a, b)
    best = INF
    u = 1
    while u * big + small <= n:            # ponytail: O(n / max(a,b)) scan; fine for OA-sized n
        rest = n - u * big
        if rest % small == 0:
            v = rest // small
            if gcd(u, v) == 1:
                best = min(best, cf_steps(u, v))
        u += 1
    return best

def same_sign(a: int, b: int, n: int) -> float:
    if a < 0 or b < 0:                     # both <= 0: mirror the problem
        a, b, n = -a, -b, -n
    if n in (a, b):
        return 0
    if a == 0 and b == 0:
        return INF
    if a == 0 or b == 0:                   # (0, x) -> (x, x) is the only useful move
        x = a + b
        return 1 + same_sign(x, x, n)
    return positive(a, b, n)

def reach_a_given_number(A: int, B: int, N: int) -> str:
    # mixed signs: BFS until both values share a sign, then switch to the closed form
    best = INF
    seen = {(A, B)}
    queue = deque([(A, B, 0)])
    while queue and len(seen) < 200000:    # ponytail: capped BFS for the mixed-sign phase
        a, b, d = queue.popleft()
        if d >= best:
            continue
        if N in (a, b):
            best = min(best, d)
            continue
        if (a >= 0) == (b >= 0) or a == 0 or b == 0:
            best = min(best, d + same_sign(a, b, N))
            continue
        for nxt in ((a + b, b), (a, a + b)):
            if nxt not in seen:
                seen.add(nxt)
                queue.append((*nxt, d + 1))
    return "NOT POSSIBLE" if best == INF else str(best)
